        return None
    segment_size, _version, frames, head, full_fingerprint = binding
    boundary = progress["boundary"]
    if segment_size != progress["segment_size"]:
        return None
    if frames != progress["frames"] or head != progress["head"]:
        return None
    if not hmac.compare_digest(full_fingerprint, progress["index"]):
        return None
    if last_complete_seq != boundary["seq"]:
        return None
    if last_complete_digest is None or not hmac.compare_digest(
        last_complete_digest, boundary["digest"]
    ):
        return None
    return progress, complete_fingerprint.hexdigest()

